parameters.jsCode:
// Marca en Baserow 152 que este SQL se mandó, para que el feed nuevo de
// Google Ads (Data Manager, "enhanced conversions for leads") lo recoja
// después. Data Manager solo LEE un archivo por HTTPS — no acepta un push
// por evento como Meta CAPI — así que Baserow 152 hace de cola compartida
// entre el envío a Meta (que ya pasó, arriba en esta misma cadena) y ese
// feed nuevo.
const fila = ((($('Baserow - Meta ids').first().json.results) || [])[0]) || null;
if (!fila || !fila.id) {
  return [{ json: { marcado: false, motivo: 'sin_fila_baserow' } }];
}

const hoy = new Date().toISOString().slice(0, 10);
try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: 'https://core.oacg.cl/api/database/rows/table/152/' + fila.id + '/?user_field_names=true',
    headers: { Authorization: 'Token __BASEROW_TOKEN__' },
    body: { '🎯 SQL a Google': hoy },
    json: true,
    timeout: 15000,
  });
  return [{ json: { marcado: true, rowId: fila.id, fecha: hoy } }];
} catch (e) {
  // No bloquea nada: el envío a Meta ya pasó. Si esto falla, el respaldo de
  // Baserow («OACG TECH | SQL Conversión Alto Valor») lo termina marcando
  // igual en su próxima barrida.
  return [{ json: { marcado: false, motivo: 'error_patch', error: String((e && e.message) || e) } }];
}
